static inline int cctrue(int cc)
{
    uae_u64 cznv = GET_CZNV();
    switch (cc) {
    case 0: return 1;
    case 1: return 0;
    case 2: return (cznv & (FLAGVAL_C | FLAGVAL_Z)) == 0;
    case 3: return (cznv & (FLAGVAL_C | FLAGVAL_Z)) != 0;
    case 4: return (cznv & FLAGVAL_C) == 0;
    case 5: return (cznv & FLAGVAL_C) != 0;
    case 6: return (cznv & FLAGVAL_Z) == 0;
    case 7: return (cznv & FLAGVAL_Z) != 0;
    case 8: return (cznv & FLAGVAL_V) == 0;
    case 9: return (cznv & FLAGVAL_V) != 0;
    case 10: return (cznv & FLAGVAL_N) == 0;
    case 11: return (cznv & FLAGVAL_N) != 0;
    case 12: return (((cznv << (FLAGBIT_N - FLAGBIT_V)) ^ cznv) & FLAGVAL_N) == 0;
    case 13: return (((cznv << (FLAGBIT_N - FLAGBIT_V)) ^ cznv) & FLAGVAL_N) != 0;
    case 14:
        cznv &= (FLAGVAL_N | FLAGVAL_Z | FLAGVAL_V);
        return (((cznv << (FLAGBIT_N - FLAGBIT_V)) ^ cznv) & (FLAGVAL_N | FLAGVAL_Z)) == 0;
    case 15:
        cznv &= (FLAGVAL_N | FLAGVAL_Z | FLAGVAL_V);
        return (((cznv << (FLAGBIT_N - FLAGBIT_V)) ^ cznv) & (FLAGVAL_N | FLAGVAL_Z)) != 0;
    }
    abort();
}
void cpu_restore_fixup(void)
{
	if (mmufixup[0].reg >= 0) {
		m68k_areg(regs, mmufixup[0].reg & 15) = mmufixup[0].value;
		mmufixup[0].reg = -1;
	}
	if (mmufixup[1].reg >= 0) {
		m68k_areg(regs, mmufixup[1].reg & 15) = mmufixup[1].value;
		mmufixup[1].reg = -1;
	}
}
void m68k_do_rte_mmu040 (uaecptr a7)
{
	uae_u16 ssr = get_word_mmu040 (a7 + 8 + 4);
	if (ssr & MMU_SSW_CT) {
		uaecptr src_a7 = a7 + 8 - 8;
		uaecptr dst_a7 = a7 + 8 + 52;
		put_word_mmu040 (dst_a7 + 0, get_word_mmu040 (src_a7 + 0));
		put_long_mmu040 (dst_a7 + 2, get_long_mmu040 (src_a7 + 2));
		// skip this word
		put_long_mmu040 (dst_a7 + 8, get_long_mmu040 (src_a7 + 8));
	}
	if (ssr & MMU_SSW_CM) {
		mmu040_movem = 1;
		mmu040_movem_ea = get_long_mmu040 (a7 + 8);
#if MMUDEBUGMISC > 0
		write_log (_T("MMU restarted MOVEM EA=%08X\n"), mmu040_movem_ea);
#endif
	}
	if (mmu_restart) {
		set_special(SPCFLAG_MMURESTART);
	}
}
void m68k_do_rts_mmu040 (void)
{
	uaecptr stack = m68k_areg (regs, 7);
	uaecptr newpc = get_long_mmu040 (stack);
	m68k_areg (regs, 7) += 4;
	m68k_setpc (newpc);
}
void m68k_do_bsr_mmu040 (uaecptr oldpc, uae_s32 offset)
{
	uaecptr newstack = m68k_areg (regs, 7) - 4;
	put_long_mmu040 (newstack, oldpc);
	m68k_areg (regs, 7) -= 4;
	m68k_incpci (offset);
}
